const tracks=[
 {id:'cidadania',name:'Reconhecer minha cidadania',tag:'DA ORIGEM AO RECONHECIMENTO',description:'Entenda os caminhos possíveis e organize cada etapa da sua jornada de cidadania italiana.',groups:[['Seu ponto de partida',['boas-vindas','caminhos']],['Prepare sua documentação',['genealogia','certidoes','traducao']],['Conheça as vias de reconhecimento',['consular','judicial','administrativa']],['Depois do reconhecimento',['aire','passaporte']]]},
 {id:'mudanca',name:'Planejar minha mudança',tag:'DO BRASIL À ITÁLIA',description:'Prepare sua chegada: região, moradia, documentação e os primeiros passos em um novo país.',groups:[['Planejamento da mudança',['boas-vindas','regioes','orcamento']],['Organize sua chegada',['moradia','documentos','pets']],['Estabeleça sua residência',['residencia','permesso','identidade']]]},
 {id:'vida',name:'Construir minha vida na Itália',tag:'SEU NOVO CAPÍTULO',description:'Explore trabalho, estudos e vida em família para construir sua rotina na Itália.',groups:[['Prepare seu novo começo',['boas-vindas','italiano']],['Trabalho e formação',['trabalho','diploma']],['Vida em família',['escola','saude','comunidade']]]}
];
const courses={
 'boas-vindas':{title:'Comece por aqui',symbol:'✦',category:'BOAS-VINDAS',lessons:['Sua jornada começa aqui','Como usar as trilhas'],description:'Conheça a plataforma e escolha por onde começar a planejar sua vida na Itália.'},
 'caminhos':{title:'Caminhos da cidadania',symbol:'⌘',category:'CIDADANIA ITALIANA',lessons:['Entenda seu ponto de partida','Conheça as vias de reconhecimento'],description:'Uma introdução aos temas que precisam ser avaliados antes de escolher uma via de reconhecimento.'},
 'genealogia':{title:'Sua história familiar',symbol:'♧',category:'DOCUMENTAÇÃO',lessons:['Organizando a linha familiar','Fontes para pesquisa'],description:'Organize as informações da sua família e prepare sua pesquisa documental.'},
 'certidoes':{title:'Certidões e documentos',symbol:'▤',category:'DOCUMENTAÇÃO',lessons:['Organização do acervo','Conferência das informações'],description:'Conheça o planejamento de uma pasta documental e os pontos a conferir.'},
 'traducao':{title:'Traduções e apostilas',symbol:'文',category:'DOCUMENTAÇÃO',lessons:['Preparando os documentos','Traduções e apostilamento'],description:'Entenda os temas de tradução e autenticação que fazem parte do planejamento.'},
 'consular':{title:'Via consular',symbol:'⌂',category:'CIDADANIA ITALIANA',lessons:['Visão geral da via consular','Preparando o acompanhamento'],description:'Conheça a estrutura do caminho consular para quem está no Brasil.'},
 'judicial':{title:'Via judicial',symbol:'⚖',category:'CIDADANIA ITALIANA',lessons:['Visão geral da via judicial','Documentos e acompanhamento'],description:'Entenda os temas envolvidos em um processo judicial e na escolha de acompanhamento profissional.'},
 'administrativa':{title:'Reconhecimento na Itália',symbol:'◇',category:'CIDADANIA ITALIANA',lessons:['Visão geral da via administrativa','Planejamento da estadia'],description:'Conheça os temas de reconhecimento na Itália e sua relação com o planejamento da mudança.'},
 'aire':{title:'AIRE e vida no exterior',symbol:'◎',category:'APÓS O RECONHECIMENTO',lessons:['Conhecendo o AIRE','Organizando suas atualizações'],description:'Prepare-se para aprender sobre cadastro e manutenção de informações de residência no exterior.'},
 'passaporte':{title:'Passaporte italiano',symbol:'▣',category:'APÓS O RECONHECIMENTO',lessons:['Planejamento da solicitação','Organizando os próximos passos'],description:'Uma introdução à organização para solicitar documentos após o reconhecimento.'},
 'regioes':{title:'Onde morar na Itália?',symbol:'⌖',category:'PLANEJE SUA MUDANÇA',lessons:['O que importa para sua escolha','Comparando regiões e cidades'],description:'Defina suas prioridades: rotina, clima, mobilidade, trabalho e proximidade da sua rede de apoio.'},
 'orcamento':{title:'Planejamento financeiro',symbol:'€',category:'PLANEJE SUA MUDANÇA',lessons:['Categorias do orçamento','Construindo uma reserva'],description:'Organize as categorias de custos para elaborar seu próprio plano de mudança.'},
 'moradia':{title:'Encontrando seu lar',symbol:'⌂',category:'CHEGADA À ITÁLIA',lessons:['Preparando a busca por moradia','Pontos para avaliar em um imóvel'],description:'Prepare sua busca por moradia a partir das necessidades da sua família.'},
 'documentos':{title:'Documentos para a chegada',symbol:'▤',category:'CHEGADA À ITÁLIA',lessons:['Sua pasta de viagem','Organizando a chegada'],description:'Conheça os temas documentais que precisam entrar no seu planejamento.'},
 'pets':{title:'Meu pet vai comigo',symbol:'♡',category:'CHEGADA À ITÁLIA',lessons:['Planejando a viagem do pet','Preparação e transporte'],description:'Organize o planejamento da viagem e a adaptação do seu animal de estimação.'},
 'residencia':{title:'Residência na Itália',symbol:'⌖',category:'VIDA NA ITÁLIA',lessons:['Introdução à residência','Organização dos próximos passos'],description:'Conheça os temas de registro de residência que fazem parte da chegada.'},
 'permesso':{title:'Permesso e família',symbol:'▣',category:'VIDA NA ITÁLIA',lessons:['Ponto de partida da família','Temas de permanência e documentação'],description:'Prepare-se para estudar as questões de permanência e documentação familiar.'},
 'identidade':{title:'Identidade italiana',symbol:'▤',category:'VIDA NA ITÁLIA',lessons:['Conhecendo a CIE','Planejando seus documentos'],description:'Conheça os temas de identidade e organização documental na Itália.'},
 'italiano':{title:'Italiano para o dia a dia',symbol:'Ciao',category:'SEU NOVO CAPÍTULO',lessons:['Primeiras interações','Construindo uma rotina de estudo'],description:'Planeje o aprendizado do idioma para situações da vida cotidiana.'},
 'trabalho':{title:'Trabalhar na Itália',symbol:'↗',category:'TRABALHO E FORMAÇÃO',lessons:['Seu plano profissional','Currículo e busca por oportunidades'],description:'Organize sua trajetória profissional e prepare uma estratégia de busca por trabalho.'},
 'diploma':{title:'Diplomas e profissões',symbol:'◇',category:'TRABALHO E FORMAÇÃO',lessons:['Sua formação e seus objetivos','Temas de reconhecimento profissional'],description:'Mapeie os temas de reconhecimento de formação relacionados à sua área de atuação.'},
 'escola':{title:'Escola e adaptação',symbol:'▱',category:'VIDA EM FAMÍLIA',lessons:['Planejando os estudos dos filhos','Adaptação escolar'],description:'Prepare a família para conversar sobre escola, idioma e adaptação.'},
 'saude':{title:'Saúde e bem-estar',symbol:'+',category:'VIDA EM FAMÍLIA',lessons:['Planejamento dos cuidados','Organizando informações de saúde'],description:'Inclua os cuidados de saúde e bem-estar no planejamento da mudança.'},
 'comunidade':{title:'Uma nova rotina',symbol:'♡',category:'VIDA EM FAMÍLIA',lessons:['Sua rede de apoio','Construindo novos vínculos'],description:'Pense em formas de criar vínculos e organizar uma rotina no novo país.'}
};
const main=document.querySelector('main');
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
let state={favorites:[],history:[],active:'cidadania',notes:{},tasks:[]};
try{const saved=JSON.parse(localStorage.getItem('partiu-preview')||'null');if(saved&&typeof saved==='object'){state={...state,...saved};state.favorites=Array.isArray(saved.favorites)?saved.favorites.filter(x=>courses[x]):[];state.history=Array.isArray(saved.history)?saved.history.filter(x=>courses[x]):[];state.tasks=Array.isArray(saved.tasks)?saved.tasks.filter(x=>['objetivo','trilha'].includes(x)):[];state.notes=saved.notes&&typeof saved.notes==='object'?saved.notes:{};if(!tracks.some(t=>t.id===state.active))state.active='cidadania';}}catch{}
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('partiu-preview',JSON.stringify(state));return true;}catch{toast('Não foi possível salvar neste navegador.');return false;}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3500);}
function updateBar(){document.querySelector('#active-name').textContent=tracks.find(t=>t.id===state.active).name;document.querySelector('.active-path').href='#trilha/'+state.active;document.querySelector('#xp').value=state.tasks.length*10;document.querySelector('#xp-count').textContent=state.tasks.length*10+' XP';}
function poster(id){const c=courses[id];return `<a href="#aula/${id}/0" class="poster ${id==='regioes'?'poster-photo':''}"><span>${c.category}</span><div class="course-symbol" aria-hidden="true">${c.symbol}</div><div class="poster-copy"><small>${id==='boas-vindas'?'GUIA DE BOAS-VINDAS':'EM PRODUÇÃO'}</small><h3>${c.title}</h3><small>${c.lessons.length} aulas planejadas</small></div></a>`;}
function catalog(title,ids){return `<details class="catalog" open><summary>${title}</summary><div class="poster-grid">${ids.map(poster).join('')}</div></details>`;}
function home(){main.innerHTML=`<div class="container"><section class="hero"><span class="eyebrow">CONHECIMENTO PARA IR MAIS LONGE</span><h1>Seu próximo capítulo<br>começa na Itália.</h1><p>Da descoberta das suas raízes à construção de uma nova vida.<br>Encontre o caminho que faz sentido para você.</p><span class="hero-stamp">🇮🇹 Benvenuto à sua jornada</span></section><form class="searchbar" role="search"><span aria-hidden="true">⌕</span><input id="search" aria-label="Buscar trilhas e assuntos" placeholder="O que você quer aprender hoje?" autocomplete="off"><button aria-label="Buscar">→</button></form><div id="search-results" class="hidden"></div><div id="home-content"><div class="section-title"><h2>${state.history.length?'Continue explorando':'Seu primeiro passo'}</h2><span class="muted">No seu ritmo, no seu caminho.</span></div><section class="resume"><span class="play-small">▷</span><div><h3>${state.history.length?courses[state.history[0]].title:'Vamos planejar sua jornada?'}</h3><p>${state.history.length?'Retome o último assunto que você visitou.':'Conheça as trilhas e descubra por onde começar.'}</p></div><a class="primary" href="#aula/${state.history[0]||'boas-vindas'}/0">${state.history.length?'Continuar':'Começar agora'} →</a></section><div class="section-title"><div><h2>Qual é o seu próximo destino?</h2><p>Trilhas de conhecimento para cada momento da sua jornada.</p></div><span class="muted">3 trilhas</span></div><section class="tracks" aria-label="Trilhas">${tracks.map((t,i)=>`<a href="#trilha/${t.id}" class="track"><div class="topline"><span>TRILHA 0${i+1}</span><span class="pill">${t.groups.flatMap(g=>g[1]).length} módulos</span></div><div class="track-info"><h3>${t.name}</h3><p>${t.description}</p><div class="track-link"><span>Explorar trilha →</span><span>0%</span></div></div></a>`).join('')}</section><details class="catalog" open><summary>Seja bem-vindo!</summary><div class="welcome-row">${poster('boas-vindas')}<div class="welcome-note"><span class="eyebrow">TUDO COMEÇA COM UM PASSO</span><h3>Uma jornada grande.<br>Pequenas etapas.</h3><p>Explore os assuntos, escolha uma trilha e prepare seu plano. As videoaulas estão em produção; por enquanto, você já pode conhecer o caminho.</p></div></div></details>${catalog('Cidadania italiana',['caminhos','consular','judicial','administrativa','certidoes'])}${catalog('Da mudança aos primeiros dias',['regioes','moradia','residencia','documentos','pets'])}${catalog('Uma nova vida na Itália',['trabalho','diploma','escola','italiano','comunidade'])}</div></div>`;
const input=document.querySelector('#search');const search=()=>{const q=input.value.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();document.querySelector('#home-content').classList.toggle('hidden',!!q);const results=document.querySelector('#search-results');results.classList.toggle('hidden',!q);const ids=Object.keys(courses).filter(id=>(courses[id].title+' '+courses[id].category).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));results.innerHTML=`<div class="section-title"><h2>${ids.length} assuntos encontrados</h2></div>${ids.length?`<div class="poster-grid">${ids.map(poster).join('')}</div>`:'<div class="empty"><h2>Nenhum assunto encontrado</h2><p>Tente buscar por cidadania, documentos, trabalho ou residência.</p></div>'}`;};input.addEventListener('input',search);document.querySelector('.searchbar').onsubmit=e=>{e.preventDefault();search();};}
function trail(id){const t=tracks.find(t=>t.id===id);if(!t)return notfound();main.innerHTML=`<div class="container narrow"><a class="back" href="#inicio">← Voltar ao início</a><section class="hero track-hero"><span class="eyebrow">${t.tag}</span><h1>${t.name}</h1><p>${t.description}</p></section><div class="path-head"><div><h2>Seu caminho de aprendizado</h2><small>Videoaulas em produção · 0% concluído</small></div><button class="outline" id="activate">${state.active===id?'✓ Trilha selecionada':'✦ Selecionar trilha'}</button></div><progress max="100" value="0" aria-label="Progresso da trilha"></progress><div class="path">${t.groups.map(([name,ids])=>`<section class="stage"><h2>${name}</h2><div class="nodes">${ids.map(cid=>`<a class="node ${cid==='boas-vindas'?'current':''}" href="#aula/${cid}/0"><span class="node-circle">${cid==='boas-vindas'?'▷':'♧'}</span><strong>${courses[cid].title}</strong><small>${cid==='boas-vindas'?'Conhecer':'Em produção'}</small></a>`).join('')}</div></section>`).join('')}</div></div>`;document.querySelector('#activate').onclick=()=>{state.active=id;save();updateBar();document.querySelector('#activate').textContent='✓ Trilha selecionada';toast('Trilha selecionada neste navegador.');};}
function lesson(id,index){const c=courses[id];if(!c||!Number.isInteger(index)||index<0||index>=c.lessons.length)return notfound();state.history=[id,...state.history.filter(x=>x!==id)].slice(0,30);save();const track=tracks.find(t=>t.id===state.active&&t.groups.some(g=>g[1].includes(id)))||tracks.find(t=>t.groups.some(g=>g[1].includes(id)));main.innerHTML=`<div class="lesson-layout"><article class="lesson-main"><div class="crumb"><a href="#inicio">Início</a> › <a href="#trilha/${track.id}">${track.name}</a> › ${c.title}</div><span class="eyebrow">${c.category}</span><h1>${c.lessons[index]}</h1><p class="description">${c.description}</p><div class="lesson-actions"><button class="outline" id="favorite" aria-pressed="${state.favorites.includes(id)}">${state.favorites.includes(id)?'★ Salvo nos favoritos':'☆ Salvar nos favoritos'}</button></div><div class="video-empty"><span aria-hidden="true">▷</span><h2>Esta videoaula está em produção</h2><p>Estamos preparando este conteúdo. Enquanto isso, explore os assuntos previstos e organize suas anotações.</p></div>${id==='boas-vindas'?'<p class="description">Comece escolhendo uma das três trilhas na página inicial. Cada trilha reúne assuntos em uma sequência sugerida. Você pode explorar o programa de cada módulo antes de as aulas ficarem disponíveis.</p>':''}<div class="tabs" role="tablist" aria-label="Recursos da aula"><button role="tab" id="tab-tasks" aria-controls="panel" aria-selected="true" data-tab="tasks">☑ Tarefas</button><button role="tab" id="tab-notes" aria-controls="panel" aria-selected="false" tabindex="-1" data-tab="notes">▤ Minhas anotações</button><button role="tab" id="tab-questions" aria-controls="panel" aria-selected="false" tabindex="-1" data-tab="questions">☏ Dúvidas</button></div><div id="panel" class="tabcontent" role="tabpanel" aria-labelledby="tab-tasks"></div><div class="lesson-end"><a class="back" href="#trilha/${track.id}">← Ver caminho da trilha</a>${index+1<c.lessons.length?`<a class="outline" href="#aula/${id}/${index+1}">Próximo assunto →</a>`:'<span class="muted">Fim do programa deste módulo</span>'}</div></article><aside class="lesson-sidebar"><h2>${c.title}</h2><small>PROGRESSO DO MÓDULO</small><progress max="100" value="0" aria-label="Progresso do módulo"></progress><p class="muted">0 de ${c.lessons.length} aulas concluídas</p><details open><summary>PROGRAMA DO MÓDULO</summary>${c.lessons.map((name,i)=>`<a class="lesson-row ${i===index?'selected':''}" href="#aula/${id}/${i}" ${i===index?'aria-current="page"':''}><span>▷</span><span>${name}<small>Em produção</small></span></a>`).join('')}</details><p class="muted">As etapas serão liberadas conforme a publicação das aulas.</p></aside></div>`;
document.querySelector('#favorite').onclick=()=>{const exists=state.favorites.includes(id);state.favorites=exists?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();const b=document.querySelector('#favorite');b.textContent=exists?'☆ Salvar nos favoritos':'★ Salvo nos favoritos';b.setAttribute('aria-pressed',String(!exists));toast(exists?'Removido dos favoritos.':'Salvo nos favoritos deste navegador.');};
function tab(which){document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===which));b.tabIndex=b.dataset.tab===which?0:-1;});const panel=document.querySelector('#panel');panel.setAttribute('aria-labelledby','tab-'+which);if(which==='tasks'){panel.innerHTML=id==='boas-vindas'?`<h3>Prepare seu primeiro passo</h3>${[['objetivo','Defini o que quero aprender primeiro.'],['trilha','Explorei uma trilha que combina com meu objetivo.']].map(([key,label])=>`<label class="task"><input type="checkbox" data-task="${key}" ${state.tasks.includes(key)?'checked':''}><span>${label}</span><small>+ 10 XP</small></label>`).join('')}<p class="note-status">Atividades de planejamento · Progresso salvo apenas neste navegador.</p>`:'<h3>Atividades em preparação</h3><p class="muted">As tarefas deste módulo acompanharão a publicação das videoaulas.</p>';panel.querySelectorAll('[data-task]').forEach(el=>el.onchange=()=>{state.tasks=el.checked?[...new Set([...state.tasks,el.dataset.task])]:state.tasks.filter(x=>x!==el.dataset.task);save();updateBar();});}else if(which==='notes'){panel.innerHTML=`<h3>Minhas anotações</h3><textarea aria-label="Anotações privadas" placeholder="Anote suas ideias e perguntas para este assunto…">${escapeHtml(state.notes[id+'/'+index]||'')}</textarea><p class="note-status">Anotações salvas apenas neste navegador.</p>`;panel.querySelector('textarea').oninput=e=>{state.notes[id+'/'+index]=e.target.value;const ok=save();panel.querySelector('.note-status').textContent=ok?'Salvo neste navegador.':'Não foi possível salvar. Copie suas anotações para preservá-las.';};}else{panel.innerHTML='<h3>Espaço para dúvidas</h3><p class="muted">As conversas com os instrutores serão abertas com o lançamento dos cursos. Por enquanto, registre suas perguntas em “Minhas anotações”.</p>';}}
document.querySelectorAll('[data-tab]').forEach((b,i)=>{b.onclick=()=>tab(b.dataset.tab);b.onkeydown=e=>{const bs=[...document.querySelectorAll('[data-tab]')];let next;if(e.key==='ArrowRight')next=(i+1)%bs.length;if(e.key==='ArrowLeft')next=(i+bs.length-1)%bs.length;if(e.key==='Home')next=0;if(e.key==='End')next=bs.length-1;if(next!==undefined){e.preventDefault();bs[next].focus();tab(bs[next].dataset.tab);}};});tab('tasks');}
function collection(type){const fav=type==='favoritos';const ids=fav?state.favorites:state.history;main.innerHTML=`<div class="container narrow"><h1 class="page-title">${fav?'☆ Favoritos':'◷ Histórico'}</h1><p class="muted">${fav?'Seus assuntos salvos para explorar depois.':'Os últimos módulos que você visitou.'} Disponível apenas neste navegador.</p>${ids.length?`<div class="poster-grid">${ids.map(poster).join('')}</div>`:`<div class="empty"><span class="empty-icon">${fav?'☆':'◷'}</span><h2>${fav?'Seus próximos interesses ficam aqui':'Sua jornada ainda está começando'}</h2><p>${fav?'Abra um módulo e toque em “Salvar nos favoritos” para encontrá-lo nesta página.':'Explore os cursos para acompanhar os módulos que você visitou.'}</p><a class="primary" href="#inicio">Explorar os cursos →</a></div>`}</div>`;}
function agenda(){main.innerHTML='<div class="container narrow"><h1 class="page-title">▦ Agenda</h1><p class="muted">Encontros ao vivo, mentorias e datas importantes.</p><div class="tabs" role="tablist" aria-label="Período da agenda"><button role="tab" aria-controls="agenda-panel" id="upcoming" aria-selected="true">Próximos</button><button role="tab" aria-controls="agenda-panel" id="past" aria-selected="false" tabindex="-1">Passados</button></div><div class="empty" id="agenda-panel" role="tabpanel" aria-labelledby="upcoming"></div></div>';const set=past=>{document.querySelector('#agenda-panel').innerHTML=`<span class="empty-icon">▦</span><h2>${past?'Ainda não realizamos encontros':'Novos encontros vêm por aí'}</h2><p>${past?'As informações dos encontros realizados aparecerão aqui.':'A programação será publicada junto com os cursos. Ainda não há encontros agendados.'}</p><a class="outline" href="#inicio">Conhecer as trilhas →</a>`;document.querySelector('#agenda-panel').setAttribute('aria-labelledby',past?'past':'upcoming');for(const b of document.querySelectorAll('[role=tab]')){const selected=(b.id==='past')===past;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;}};for(const id of ['upcoming','past']){const b=document.getElementById(id);b.onclick=()=>set(id==='past');b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const past=e.key==='End'||(e.key!=='Home'&&id==='upcoming');set(past);document.getElementById(past?'past':'upcoming').focus();}};}set(false);}
function support(){main.innerHTML='<div class="container narrow"><h1 class="page-title">Como podemos ajudar?</h1><p class="muted">Conheça esta primeira versão do Partiu Itália.</p><div class="support-grid"><article><h2>Quando as aulas estarão disponíveis?</h2><p>Os cursos estão em preparação. As datas de lançamento ainda não foram definidas. O programa apresentado organiza os temas previstos para gravação.</p></article><article><h2>Como funcionam as trilhas?</h2><p>Escolha uma trilha, conheça suas etapas e abra os módulos para explorar o programa. A seleção da trilha ajuda você a retomar seu caminho.</p></article><article><h2>Onde ficam minhas anotações?</h2><p>Nesta prévia, favoritos, anotações e atividades de planejamento ficam apenas no navegador atual. Eles não são sincronizados entre dispositivos.</p></article><article><h2>Como falar com um instrutor?</h2><p>O canal de atendimento e o espaço de dúvidas serão disponibilizados no lançamento. Você pode preparar suas perguntas na área de anotações.</p></article></div></div>';}
function notfound(){main.innerHTML='<div class="container"><div class="empty"><h1>Não encontramos esta página</h1><a class="primary" href="#inicio">Voltar ao início</a></div></div>';}
function render(){const parts=location.hash.slice(1).split('/');const route=parts[0]||'inicio';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('selected',a.dataset.nav===route);if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(route==='inicio')home();else if(route==='trilha')trail(parts[1]);else if(route==='aula')lesson(parts[1],Number(parts[2]||0));else if(route==='agenda')agenda();else if(['favoritos','historico'].includes(route))collection(route);else if(route==='suporte')support();else notfound();updateBar();window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true});});render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_learning_path',title:'Abrir trilha de aprendizado',description:'Abre a trilha escolhida no Partiu Itália sem alterar o progresso.',inputSchema:{type:'object',properties:{path:{type:'string',enum:tracks.map(t=>t.id)}},required:['path'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!tracks.some(t=>t.id===input.path))throw new Error('Trilha inválida');location.hash='trilha/'+input.path;render();return{path:input.path,title:tracks.find(t=>t.id===input.path).name};}})).catch(()=>{});}catch{}}
